const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const {x: spiral} = IO.loadSpiralData({turns: 0.5});
const model = HKmeans.new(spiral, {rho: 0.1, kmeansIter: 2}).fit();
const udf = point => model.udf(point, 1);

const padding = 0.1;
const min = [0, 1].map(axis => Math.min(...spiral.map(point => point.components[axis])) - padding);
const max = [0, 1].map(axis => Math.max(...spiral.map(point => point.components[axis])) + padding);
const randomPoint = () => vec(...min.map((value, axis) => value + Math.random() * (max[axis] - value)));
const nearSpiral = () => {
    const point = spiral[Math.floor(Math.random() * spiral.length)];
    return vec(...point.components.map((value, axis) =>
        Math.max(min[axis], Math.min(max[axis], value + 0.2 * (Math.random() - 0.5)))
    ));
};

// Central differences approximate the UDF gradient away from its non-differentiable points.
const h = 0.001;
const gradient = point => {
    const dx = vec(h, 0);
    const dy = vec(0, h);
    return vec(
        (udf(point.add(dx)) - udf(point.sub(dx))) / (2 * h),
        (udf(point.add(dy)) - udf(point.sub(dy))) / (2 * h),
    );
};
const samples = Array.from({length: 10000}, (_, i) => {
    const point = i % 2 === 0 ? randomPoint() : nearSpiral();
    return {point, gradient: gradient(point)};
});

// The network learns the gradient; its negative is used as the flow velocity.
const field = NeuralNet.builder()
    .input(2)
    .layer(24)
    .layer(24)
    .layer(2, NeuralNet.ACTIVATIONS.linear)
    .build();
const initial = Array.from({length: 400}, randomPoint);
const plot = IO.plotPointCloud(spiral, {aspect: "equal", radius: 0.012, color: [0.4, 0.4, 0.4]});
const moving = plot.add(initial, {radius: 0.015, color: [1, 0, 0]});
const arrows = plot.addLines([], {color: [0.35, 0.65, 1]});
plot.add([min, max], {color: [0, 0, 0]});
const steps = 100;
let trajectory;

const fieldLines = () => {
    const lines = [];
    for (let i = 0; i <= 8; i++) {
        for (let j = 0; j <= 8; j++) {
            const start = vec(min[0] + i * (max[0] - min[0]) / 8, min[1] + j * (max[1] - min[1]) / 8);
            const velocity = vec(...field.eval(start)).scale(-1);
            const length = velocity.length();
            if (length < 1e-8) continue;
            const delta = velocity.scale(Math.min(0.1, 0.14 / length));
            const end = start.add(delta);
            const [dx, dy] = delta.components;
            const head = delta.scale(0.3);
            const side = vec(-dy, dx).scale(0.15);
            lines.push([start, end], [end, end.sub(head).add(side)], [end, end.sub(head).sub(side)]);
        }
    }
    return lines;
};
const showTime = t => {
    if (!trajectory) return;
    moving.update(trajectory[Math.round(t * steps)], {color: [1 - t, t, 0]});
    plot.render();
};
const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
        onChange: showTime,
    })},
);

const {theta} = await fitDataAsync(
    samples.map(sample => sample.point),
    samples.map(sample => sample.gradient),
    field.model,
    {
        epochs: 5000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.005}),
        continuationEvery: 250,
        continuationFn: ({epoch, loss}) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

// Precompute trajectories so the slider can move both forwards and backwards.
trajectory = [initial];
for (let step = 0; step < steps; step++) {
    trajectory.push(trajectory[step].map(point => {
        const velocity = vec(...field.eval(point)).scale(-1);
        return point.add(velocity.scale(1 / steps));
    }));
}
arrows.update(fieldLines());
showTime(0);
ui;
